sql.if:
AND EXISTS ( SELECT medata_set_id FROM ( SELECT t3.medata_set_id FROM dtmeta.tb_meta_data t3 INNER JOIN dtmeta.tb_meta_model t7 ON t3.val_model_id = t7.model_id LEFT OUTER JOIN dtmeta.tb_portal_code c3 ON t7.data_type_mtcd = c3.mtcd AND c3.mtcd_grp_id = 'MCG00013' WHERE 1=1
AND t3.medata_id = #{medataId}
AND t3.medata_set_id = #{medataSetId}
AND t3.prpty_id = #{prptyId}
AND t3.val_model_id = #{valModelId}
AND t3.medata_val = #{medataVal}
AND t3.medata_val ILIKE CONCAT('%', #{srchVal}, '%')
AND t3.lang_mtcd = #{langMtcd}
AND c3.mtcd IS NOT NULL
AND c3.mtcd IS NULL
INTERSECT SELECT medata_set_id FROM dtmeta.tb_meta_data t3 INNER JOIN dtmeta.tb_meta_model t7 ON t3.val_model_id = t7.model_id WHERE t3.medata_val ILIKE CONCAT('%', #{keyword}, '%') AND t7.data_type_mtcd IN ('keywordsKo', 'keywordsEn')
INTERSECT SELECT medata_set_id FROM dtmeta.tb_meta_data t3 INNER JOIN dtmeta.tb_meta_model t7 ON t3.val_model_id = t7.model_id INNER JOIN dtmeta.tb_meta_category a1 ON a1.ctgry_id = #{ctgryId} WHERE ( t3.medata_val = a1.ctgry_id AND t7.data_type_mtcd = 'categoryId' ) OR ( t3.medata_val = a1.ctgry_rdf_cncpt_nm AND t7.data_type_mtcd = 'categoryConcept' )
INTERSECT SELECT medata_set_id FROM dtmeta.tb_meta_data t3 INNER JOIN dtmeta.tb_meta_model t7 ON t3.val_model_id = t7.model_id WHERE t3.medata_val = #{agntId} AND t7.type_model_id = 'Agent'
) t3 WHERE t3.medata_set_id = t1.medata_set_id )

mapper.insert:
		INSERT /* SQL_ID: MetadataSetMapper.insertMetadataSet */
		       INTO dtmeta.tb_meta_dataset
			 ( medata_set_id
             , model_id
             , medata_set_nm
             , medata_set_logic_nm
             , medata_set_desc
             , medata_set_sttus_mtcd
             , medata_set_sttus_why
             , medata_set_nwst_rvsn
             , medata_set_regr_id
             , medata_set_regr_nm
             , medata_set_reg_dt
             , medata_set_amdr_id
             , medata_set_amdr_nm
             , medata_set_amd_dt
			 ) VALUES 
			 ( 
			   #{medataSetId}			 			 
			 , #{modelId}
			 , #{medataSetNm}
			 , #{medataSetLogicNm}
			 , #{medataSetDesc}
			 , #{medataSetSttusMtcd}
			 , #{medataSetSttusWhy}
			 , #{medataSetNwstRvsn}
			 , #{medataSetRegrId}
			 , #{medataSetRegrNm}
			 , current_timestamp
			 , #{medataSetRegrId}
			 , #{medataSetRegrNm}
			 , current_timestamp			 
			 )

mapper.update:
		UPDATE /* SQL_ID: MetadataSetMapper.updateMetadataSet */
               dtmeta.tb_meta_dataset
		   SET model_id                 = #{modelId}
		     , medata_set_nm            = #{medataSetNm}
             , medata_set_logic_nm		= #{medataSetLogicNm}
             , medata_set_desc          = #{medataSetDesc}
             , medata_set_amdr_id       = #{medataSetAmdrId}
             , medata_set_amdr_nm       = #{medataSetAmdrNm}
             , medata_set_amd_dt        = current_timestamp            
		 WHERE medata_set_id      = #{medataSetId}

		UPDATE /* SQL_ID: MetadataSetMapper.updateMetadataSetStatus */
               dtmeta.tb_meta_dataset
		   SET medata_set_sttus_mtcd    = #{medataSetSttusMtcd}

             , medata_set_sttus_why     = #{medataSetSttusWhy}


             , medata_set_nwst_rvsn     = #{medataSetNwstRvsn}

             , medata_set_amdr_id       = #{medataSetAmdrId}
             , medata_set_amdr_nm       = #{medataSetAmdrNm}
             , medata_set_amd_dt        = current_timestamp            
         WHERE medata_set_id      = #{medataSetId}

UPDATE /* SQL_ID: MetadataSetMapper.updateMetadataSetNwstRvsn */
       dtmeta.tb_meta_dataset
   SET medata_set_nwst_rvsn     = medata_set_nwst_rvsn + 1
     , medata_set_amdr_id       = #{medataSetAmdrId}
     , medata_set_amdr_nm       = #{medataSetAmdrNm}
     , medata_set_amd_dt        = current_timestamp            
 WHERE medata_set_id      = #{medataSetId}


    SELECT medata_set_nwst_rvsn  FROM dtmeta.tb_meta_dataset  WHERE medata_set_id = #{medataSetId}

